package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TimeoutVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property timeout of smtp outbound config ")
  void test_timeout_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> TimeoutVO.tryFrom(null));
    Assertions.assertEquals(1, TimeoutVO.from(1).getTimeout());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> TimeoutVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", TimeoutVO.from(1).toString());
  }
}
